    55→            "File content is not correct",
    56→            new BlockingStorage(storage).value(
    57→                new Key.From(String.format("docker/registry/v2/blobs/sha256/05/%s/data", hash))
    58→            ),
    59→            Matchers.equalTo(bytes)
    60→        );
    61→    }
