    88→                        true,
    89→                        "3a6eb0790f39ac87c94f3856b2dd2c5d110e6811602261a9a923d3bb23adc8b7"
    90→                    )
    91→                );
    92→                MatcherAssert.assertThat(
    93→                    "Exception message contains expected digest",
    94→                    Throwables.getRootCause(throwable).getMessage(),
    95→                    new StringContains(true, digest)
    96→                );
    97→                return CompletableFuture.allOf();
    98→            }
    99→        ).join();
   100→    }
