        final InMemoryStorage storage = new InMemoryStorage();
        final AstoBlobs blobs = new AstoBlobs(
            new SubStorage(RegistryRoot.V2, storage),
            new DefaultLayout(),
            new RepoName.Simple("does not matter")
        );
